sys_script_include.script:
var ConfirmOTPViaInteraction = Class.create();
ConfirmOTPViaInteraction.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    confirmAndValidateOTP: function() {
        gs.info('[OTP SERVER LOG] Initializing OTP post-validation subflow execution.');

        try {
            var interactionId = this.getParameter('sysparm_interaction');
            var userEnteredOtp = this.getParameter('sysparm_otp_code');

            if (!interactionId) {
                return JSON.stringify({ status: 'error', message: 'Missing Interaction Sys ID.' });
            }

            // Standardize reason and confirmation message for post-OTP subflow context
            var reasonForMessage = 'Authentication Required';
            var messageToSend    = 'OTP verified successfully: ' + (userEnteredOtp || 'N/A');

            var inputs = {};
            inputs['interaction_sys_id'] = interactionId;      // String 
            inputs['reason_for_message'] = reasonForMessage;    // String 
            inputs['message_to_send']    = messageToSend;       // String 

            gs.info('[OTP SERVER LOG] Triggering Flow Runner Engine for: x_snc_pab_ee_tkit.update_interaction_post_otp');

            // Execute Synchronously in foreground to capture outputs
            var result = sn_fd.FlowAPI.getRunner()
                .subflow('x_snc_pab_ee_tkit.update_interaction_post_otp')
                .inForeground()
                .withInputs(inputs)
                .run();

            var outputs = result.getOutputs();
            var otp_message_stats = outputs['otp_message_stats'] || '';

            gs.info('[OTP SERVER LOG] OTP subflow completed. Output status: ' + otp_message_stats);

            return JSON.stringify({ 
                status: 'success', 
                notes: otp_message_stats 
            });

        } catch (ex) {
            var message = ex.getMessage ? ex.getMessage() : ex.message;
            gs.error('[OTP SERVER ERROR] Fatal OTP subflow exception: ' + message);
            return JSON.stringify({ status: 'error', message: message });
        }
    },

    type: 'ConfirmOTPViaInteraction'
});
